        self.assertEqual(len(w.invites), 6)

    def test_escalation(self):
        for who, role in [("vic", "viewer"), ("vic", "admin"), ("vic", "owner"), ("mia", "admin"), ("mia", "owner"), ("adam", "owner"), ("olga", "owner"), ("stranger", "viewer"), ("stranger", "owner"), ("", "member")]:
