import notes as m

DATA = [{"id": i, "owner": o, "text": "n%d" % i} for i, o in enumerate(["ann", "bob", "ann", "carol", "bob", "ann"], start=1)]
ANN, ADMIN = {"name": "ann", "role": "user"}, {"name": "root", "role": "admin"}


class NotesTest(unittest.TestCase):
